        # button_layout.addWidget(self.delete_button, alignment=Qt.AlignmentFlag.AlignRight)
        # layout.addLayout(button_layout)
        
    def set_ui_size(self):
        screen = QtGui.QGuiApplication.primaryScreen().availableGeometry()
        screen_width = screen.width()
        screen_height = screen.height()

        self.window_width = int(screen_width * 0.3)
        self.window_height = int(screen_height * 0.3)

        
    def save_changes(self):
        """Sends updated product data to the API"""
        nombre = self.name_input.text().strip()
        tipo = self.type_input.text().strip()
        proveedor = self.supplier_input.text().strip()
        stock_text = self.stock_input.text().strip()
        precio_text = self.precio_input.text().strip()
        
        # Validate required fields
        if not nombre:
            QMessageBox.warning(self, "Error", "El campo 'Nombre' es obligatorio.")
            return

        if not stock_text:
            QMessageBox.warning(self, "Error", "El campo 'Stock' es obligatorio.")
            return

        try:
            stock = int(stock_text)
            if stock < 0:
                raise ValueError("Stock negativo")
        except ValueError:
            QMessageBox.warning(self, "Error", "El campo 'Cantidad' debe ser un número entero no negativo.")
            return

        # Validate precio if provided
        if precio_text:
            try:
                precio = float(precio_text)
                if precio < 0:
                    raise ValueError("Precio negativo")
            except ValueError:
                QMessageBox.warning(self, "Error", "El campo 'Precio' debe ser un número decimal positivo.")
                return
        else:
            precio = 0.0  # Default value if not filled

        # Validate other optional fields as strings
        if not isinstance(tipo, str):
            QMessageBox.warning(self, "Error", "El Campo tipo de producto debe ser de texto.")
            return
        elif (tipo is None):
            tipo = ""
            
        if not isinstance(proveedor, str):
            QMessageBox.warning(self, "Error", "El Campo proveedor de producto debe ser de texto.")
            return
        elif (proveedor is None):
            proveedor = ""
            
        api_url = f"http://{URL_SERVER}/api/productos/{self.product['id']}/"
        headers = {"Authorization": f"Token {self.token}"}
        data = {
            "nombre": self.name_input.text(),
            "tipo": tipo,
            "proveedor": proveedor,
            "stock": int(self.stock_input.text()),
            "precio": float(precio)
        }
        
        try:
            response = requests.put(api_url, headers=headers, json=data)
            if response.status_code == 200:
                self.padre.show_status_message("Producto actualizado correctamente.", message_type = "success") 
                QMessageBox.information(self, "Éxito", "Producto actualizado correctamente.")
                if self.refresh_callback:
                    self.refresh_callback()
                self.accept()
            else:
                self.padre.show_status_message("No se pudo actualizar el producto.", message_type = "error") 
                QMessageBox.critical(self, "Error", "No se pudo actualizar el producto.")
        except requests.exceptions.RequestException:
            QMessageBox.critical(self, "Error", "Error de conexión con el servidor.")
    
    def confirm_delete_product(self):
        """Shows a confirmation dialog before deleting a product"""
        confirmation = QMessageBox()
        confirmation.setIcon(QMessageBox.Icon.Warning)
        confirmation.setWindowTitle("Confirmar eliminación")
        confirmation.setText("¿Está seguro de que desea eliminar este producto?")
        confirmation.setStandardButtons(QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        confirmation.setDefaultButton(QMessageBox.StandardButton.No)

        response = confirmation.exec_()

        if response == QMessageBox.StandardButton.Yes:
            self.delete_product()

    def delete_product(self):
        """Deletes the product from the UI and database"""
        api_url = f"http://{URL_SERVER}/api/productos/{self.product['id']}/"
        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Token {self.token}"
        }

        try:
            response = requests.delete(api_url, headers=headers)
            if response.status_code == 204:  # HTTP 204 No Content → Success
                if self.refresh_callback:
                    self.refresh_callback()
                self.padre.show_status_message(f"Producto {self.product['nombre']} eliminado.", message_type="success")
                
                self.accept()

            else:
                self.padre.show_status_message(f"No se pudo eliminar el producto {self.product['nombre']}.", message_type = "error") 
                QMessageBox.critical(self, "Error", "No se pudo eliminar el producto.")
        except requests.exceptions.RequestException:
            QMessageBox.critical(self, "Error", "Error de conexión con el servidor.")

