class AdminWindow(QtWidgets.QMainWindow, Ui_inventarioWindow):
    def __init__(self, token):
        super().__init__()
        self.token = token
        self.set_ui_size()
        self.setupUi(self, self.window_width, self.window_height) 
        self.setWindowTitle("Inventario Admin")
        self.stacked_widget = QStackedWidget(self)
        self.mainContainer.layout().addWidget(self.stacked_widget)
        self.init_ui()
        self.show_status_message("Conectado al servidor.") 
    
    def set_ui_size(self):
        screen = QtGui.QGuiApplication.primaryScreen().availableGeometry()
        screen_width = screen.width()
        screen_height = screen.height()

        self.window_width = int(screen_width)
        self.window_height = int(screen_height)

        x_position = (screen_width - self.window_width) // 2
        y_position = (screen_height - self.window_height) // 2

        self.setGeometry(x_position, y_position, self.window_width, self.window_height) 
        
    def init_ui(self):
        self.ventas_view = VentasView(self.token, self)
        self.historial_view = HistorialView(self.token, self)
        self.inventario_view = InventarioView(self.token, self)
        
        self.action_ventas.triggered.connect(lambda: self.switch_view(self.ventas_view, "menuventas"))
        self.action_historial.triggered.connect(lambda: self.switch_view(self.historial_view, "menuhistorial"))
        self.action_inventario.triggered.connect(lambda: self.switch_view(self.inventario_view, "menuInventario"))

        self.stacked_widget.addWidget(self.ventas_view)
        self.stacked_widget.addWidget(self.historial_view)
        self.stacked_widget.addWidget(self.inventario_view)
        
        self.switch_view(self.inventario_view, "menuInventario")
    
    def switch_view(self, widget, menu_name):
        self.set_active_menu(menu_name)  # highlight with rombus
        self.stacked_widget.setCurrentWidget(widget)
        
        is_inventario = (menu_name == "menuInventario")
        is_ventas = (menu_name == "menuventas")
        
        self.ventas_view.setVisible(is_ventas)
        self.scrollArea.setVisible(is_inventario)
        self.lineEdit.setVisible(is_inventario)
        self.pushButton.setVisible(is_inventario)
        self.label.setVisible(is_inventario)
        
        if menu_name == "menuventas":
            self.setWindowTitle("Ventas Admin")
        elif menu_name == "menuhistorial":
            self.setWindowTitle("Historial Admin")
        elif menu_name == "menuInventario":
            self.setWindowTitle("Inventario Admin")
            
