class InventarioView(QWidget):
    def __init__(self, token, parent):
        super().__init__(parent)
        self.token = token
        self.padre = parent
        self.init_ui()
        self.request_products()
        
    def init_ui(self):
        self.padre.scrollArea.setWidgetResizable(True)
        self.scroll_widget = QWidget()
        self.scroll_layout = QVBoxLayout(self.scroll_widget)
        self.padre.scrollArea.setWidget(self.scroll_widget)
        self.padre.pushButton.clicked.connect(lambda: self.open_add_dialog())
        self.product_widgets = []
        self.padre.lineEdit.textChanged.connect(self.filter_products)
        """
        self.pushButton.clicked.connect(self.add_product_entry)
        self.pushButton_2.clicked.connect(self.register_sale)
        self.add_product_entry()
        self.update_subtotal()
        """
        
    def request_products(self):
        
        api_url = "http://"+ URL_SERVER + "/api/productos/"
        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Token {self.token}"
        }
        
        try:
            response = requests.get(api_url, headers=headers)
            if response.status_code == 200:
                self.products = response.json()
                self.display_products(self.products)
            else:
                QMessageBox.critical(self, "Error", "Error al obtener productos del servidor")
        except requests.exceptions.RequestException:
            QMessageBox.critical(self, "Error", "No se pudo conectar con el servidor")
        
    def create_product_box(self, product):
        """Creates a product box with collapsible details"""
        product_frame = QFrame()
        product_frame.setStyleSheet("border: 1px solid #ccc; padding: 10px; border-radius: 5px;")
        product_frame.setCursor(Qt.CursorShape.PointingHandCursor)
        product_frame.product_info = product  # Attach product data

        outer_layout = QVBoxLayout(product_frame)

        # Header (always visible)
        header_label = QLabel(f"{product['nombre']} - Cantidad: {product['stock']}")
        header_label.setStyleSheet("font-weight: bold; border: none; font-size: 16px;")
        outer_layout.addWidget(header_label)

        # Details section (initially hidden)
        details_widget = QWidget()
        details_layout = QVBoxLayout(details_widget)

        type_label = QLabel(f"Tipo: {product['tipo']}")
        type_label.setStyleSheet("border: none;")
        proveedor_label = QLabel(f"Proveedor: {product['proveedor']}")
        proveedor_label.setStyleSheet("border: none;")
        precio_label = QLabel(f"Precio: {product['precio']}$")
        precio_label.setStyleSheet("border: none;")

        edit_button = QPushButton("Editar")
        edit_button.setStyleSheet("""
            QPushButton {
                background-color: #ff8c00;
                color: white;
                font-size: 24px;
                font-weight: bold;
                padding: 10px;
                border-radius: 10px;
            }
            QPushButton:hover {
                background-color: #ff7f50;
            }
        """)
        edit_button.setFixedWidth(100)
        edit_button.clicked.connect(lambda: self.open_edit_dialog(product))
        edit_button_layout = QHBoxLayout()
        edit_button_layout.addStretch()
        edit_button_layout.addWidget(edit_button)
        edit_button_layout.addStretch()

        details_layout.addWidget(type_label)
        details_layout.addWidget(proveedor_label)
        details_layout.addWidget(precio_label)
        details_layout.addLayout(edit_button_layout)

        details_widget.setVisible(False)
        outer_layout.addWidget(details_widget)

        # Toggle details visibility when frame is clicked
        def toggle_details():
            details_widget.setVisible(not details_widget.isVisible())

        product_frame.mousePressEvent = lambda event: toggle_details()

        return product_frame
    
    
    def display_products(self, products):
        """Display product boxes inside scroll area"""
        # Properly delete old widgets
        for widget in self.product_widgets:
            widget.setParent(None)
            widget.deleteLater()

        self.product_widgets.clear()

        # Remove all items in layout (including spacers)
        while self.scroll_layout.count():
            item = self.scroll_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

        for product in products:
            product_widget = self.create_product_box(product)
            self.scroll_layout.addWidget(product_widget)
            self.product_widgets.append(product_widget)

        self.scroll_layout.addStretch()
        
    def open_edit_dialog(self, product):
        """Opens the edit dialog for a product"""
        dialog = EditProductDialog(product, self.token, self, refresh_callback=self.request_products, padre = self.padre)
        dialog.exec_()
    
    def open_add_dialog(self):
        dialog = AddProductDialog(self.token, self, refresh_callback=self.request_products, padre = self.padre)
        dialog.exec_()
        
    def filter_products(self):
        """Filters products based on user input"""
        search_text = self.padre.lineEdit.text().strip().lower()

        for product_widget in self.product_widgets:  # Iterate over all product boxes
            product_data = product_widget.product_info  # Dictionary with product details

            # Check if the search text matches any field
            if (
                search_text in product_data["nombre"].lower()
                or search_text in product_data["tipo"].lower()
                or search_text in product_data["proveedor"].lower()
            ):
                product_widget.show()  # Show if it matches
            else:
                product_widget.hide()  # Hide if it doesn't match